import pathlib, subprocess, json, datetime, platform, hashlib
root = pathlib.Path(__file__).parent
evidence = root / 'evidence'
plan = json.loads((evidence / 'measurement-plan.json').read_text())
executables = {name: root / (name + '-build/http_server_bench')
               for name in ['before', 'poll', 'after', 'batch']}
result = {'plan': plan, 'runs': [], 'scheduling_runs': [], 'environment': {
    'uname': platform.uname()._asdict(),
    'os': subprocess.check_output(['sw_vers'], text=True),
    'cpu': subprocess.check_output(['sysctl', '-n', 'machdep.cpu.brand_string'], text=True).strip(),
    'compiler': subprocess.check_output(['clang++', '--version'], text=True),
    'started_utc': datetime.datetime.now(datetime.timezone.utc).isoformat()}}
def run(name, group, selected=None):
    command = [str(executables[name]), '--duration-ms', str(plan['duration_ms'])]
    if selected:
        command += ['--case', selected]
    output = subprocess.run(command, text=True, capture_output=True, timeout=120)
    if output.returncode:
        raise RuntimeError(f'{command}: {output.returncode}: {output.stderr}')
    report = json.loads(output.stdout)
    for case in report['cases']:
        assert case['errors'] == 0 and case['requests'] > 0
        assert case['client_pid'] != case['server_pid']
        assert case['server_thread_cpu_seconds'] > 0 and case['server_process_cpu_seconds'] > 0
    return {'group': group, 'variant': name, 'command': command, 'report': report,
            'stderr': output.stderr, 'finished_utc': datetime.datetime.now(datetime.timezone.utc).isoformat()}
def save():
    (evidence / 'measurement-raw.json').write_text(json.dumps(result, indent=2) + '\n')
for group, order in enumerate(plan['orders'], 1):
    for name in order:
        combined = run(name, group)
        for selected in ['health_idle512', 'health_idle2048']:
            extra = run(name, group, selected)
            combined['report']['cases'].extend(extra['report']['cases'])
            combined.setdefault('extra_commands', []).append(extra['command'])
        assert [c['name'] for c in combined['report']['cases']] == plan['cases']
        result['runs'].append(combined)
        save()
        cases = {c['name']: c for c in combined['report']['cases']}
        print(f"group {group} {name}: c64={cases['health_c64']['requests_per_second']:.0f}, idle2048={cases['health_idle2048']['requests_per_second']:.0f}", flush=True)
for group in range(1, 6):
    for name in (['after', 'batch'] if group % 2 else ['batch', 'after']):
        sample = run(name, group, 'health_c64')
        result['scheduling_runs'].append(sample)
        save()
    print(f'scheduling pair {group} complete', flush=True)
result['environment']['finished_utc'] = datetime.datetime.now(datetime.timezone.utc).isoformat()
save()
print('all measurements complete', flush=True)

